INSERT INTO public.pm_schedules (asset_id, title, tasks, interval_days, priority, next_due, active, season_start_md, season_end_md)
SELECT a.id, pm.title, pm.tasks, pm.interval_days, pm.priority, pm.next_due::date, true, '03-15', '11-15'
FROM pm pm
JOIN public.assets a ON a.name = pm.asset_name
WHERE NOT EXISTS (
  SELECT 1 FROM public.pm_schedules p WHERE p.asset_id = a.id AND p.title = pm.title
);